/**
 * Loads the workspace for an owner-only action. The role matrix admits any
 * owner-role holder; the recorded owner is the one allowed to act.
 */
async function loadOwnedOrg(
  actor: Actor,
  orgId: OrgId,
  action: PermissionAction,
): Promise<Organization> {
  assertCan(actor, action, orgResource(orgId));
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);

  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError(action, {
      action,
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
  return org;
}

/**
 * The offer the given member may act on. Anyone else, and any call against an
 * offer that is no longer open, is refused as `nothing_pending`; the offered
 * member alone learns that their offer has lapsed.
 */
async function openHandoverFor(
  orgId: OrgId,
  userId: UserId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/** An offer lapses at the instant `expiresAt` is reached, not after it. */
function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return Date.parse(handover.expiresAt) <= now.getTime();
}
