'''/**
 * Offers the workspace to another active member. Only the recorded owner may
 * offer, and only one offer may be open at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOwnedOrg(actor, orgId, "org:transfer_ownership");

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const previous = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (previous && !isLapsed(previous, now)) {
    throw new OwnershipHandoverError("pending_exists");
  }
  if (previous) {
    await ownershipHandoverRepo.resolveHandover(
      orgId,
      previous.id,
      "expired",
      previous.expiresAt,
    );
  }

  const createdAt = toIsoTimestamp(now);
  const handover = await ownershipHandoverRepo.insertHandover({
    orgId,
    fromUserId: org.ownerId,
    toUserId,
    createdAt,
    expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_WINDOW_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership was offered to you",
    body: `${org.name} can be handed over to you. Accept within seven days.`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes over. The new owner is promoted before the previous
 * owner is stepped down, so the workspace never lacks an owner, and the
 * last-owner rule is not consulted: this path is the one that moves it.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const pending = await openHandoverFor(orgId, actor.userId, now);
  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: incoming.id,
      from: incoming.role,
      to: "owner",
    });
  }

  await orgRepo.setOrgOwner(orgId, actor.userId);

  const outgoing = await memberRepo.findMember(orgId, pending.fromUserId);
  if (outgoing && outgoing.role === "owner") {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: outgoing.id,
      from: "owner",
      to: "admin",
    });
  }

  await ownershipHandoverRepo.resolveHandover(
    orgId,
    pending.id,
    "accepted",
    toIsoTimestamp(now),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: actor.userId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** The offered member turns the offer down; the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const pending = await openHandoverFor(orgId, actor.userId, now);
  return ownershipHandoverRepo.resolveHandover(
    orgId,
    pending.id,
    "declined",
    toIsoTimestamp(now),
  );
}

/** The recorded owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await loadOwnedOrg(actor, orgId, "org:transfer_ownership");

  const now = new Date();
  const pending = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!pending || isLapsed(pending, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

/** The open offer for the workspace, or `null` when none is open. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await ownershipHandoverRepo.findPendingHandover(orgId);
  if (!pending || isLapsed(pending, new Date())) return null;
  return pending;
}

/** The org switcher's list; no `Actor` exists until one is chosen. */''')

