/**
 * Ownership handover: offer, accept, decline, withdraw, and the seven-day lapse.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as organizationService from "@/server/services/organization-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe | undefined;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  detach?.();
  cleanup();
});

async function roleOf(tenant: Tenant, role: keyof Tenant["userIds"]): Promise<string> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error("fixture member missing");
  return member.role;
}

describe("organization-service ownership handover", () => {
  it("only the recorded owner may offer, and the owner cannot offer to themselves", async () => {
    const tenant = await createTenant("handover-guards", "growth");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.owner,
      ),
    ).rejects.toMatchObject({ reason: "self" });
  });

  it("refuses an offer to a user outside the workspace and a cross-tenant call", async () => {
    const tenant = await createTenant("handover-targets", "growth");
    const stranger = await createTenant("handover-stranger", "growth");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        stranger.userIds.member,
      ),
    ).rejects.toThrow(/was not found/);

    await expect(
      organizationService.getPendingOwnershipHandover(
        tenant.actors.owner,
        stranger.org.id,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("offers to one member, notifies only that member, and refuses a second open offer", async () => {
    const tenant = await createTenant("handover-offer", "growth");

    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(offer).toMatchObject({
      status: "pending",
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.admin,
      resolvedAt: null,
    });

    const seen = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["ownership_handover"],
      limit: 10,
      cursor: null,
    });
    expect(seen.items).toHaveLength(1);

    const others = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["ownership_handover"],
      limit: 10,
      cursor: null,
    });
    expect(others.items).toHaveLength(0);

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    const visible = await organizationService.getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(visible?.id).toBe(offer.id);
  });

  it("lets the offered member decline, after which the owner may offer again", async () => {
    const tenant = await createTenant("handover-decline", "growth");

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const declined = await organizationService.declineOwnershipHandover(
      tenant.actors.admin,
      tenant.org.id,
    );
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();

    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const reoffer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(reoffer.status).toBe("pending");
  });

  it("withdraws an open offer and refuses withdrawal when nothing is open", async () => {
    const tenant = await createTenant("handover-withdraw", "growth");

    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    const canceled = await organizationService.cancelOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(canceled.status).toBe("canceled");

    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);
    expect(
      await organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).toBeNull();
  });

  it("transfers ownership on accept: roles change, the owner is re-pointed, and the audit log records it", async () => {
    const tenant = await createTenant("handover-accept", "growth");

    const roleChanges: Array<{ memberId: string; from: string; to: string; actorId: string | null }> = [];
    const offRoles = subscribe("member.role_changed", (payload) => {
      roleChanges.push({
        memberId: payload.memberId,
        from: payload.from,
        to: payload.to,
        actorId: payload.actorId,
      });
    });

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    const org = await organizationService.acceptOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    offRoles();

    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(tenant, "viewer")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");

    expect(roleChanges).toEqual([
      expect.objectContaining({ from: "viewer", to: "owner", actorId: tenant.userIds.viewer }),
      expect.objectContaining({ from: "owner", to: "admin", actorId: tenant.userIds.viewer }),
    ]);

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.viewer,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.viewer },
    });

    // The previous owner is an admin now, so billing is refused to them.
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.admin,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("lapses seven days after the offer was made", async () => {
    const tenant = await createTenant("handover-lapse", "growth");
    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2026-05-01T10:00:00.000Z");
    vi.setSystemTime(start);

    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(offer.expiresAt).toBe("2026-05-08T10:00:00.000Z");

    vi.setSystemTime(new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000 - 1));
    expect(
      await organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).not.toBeNull();

    vi.setSystemTime(new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000));
    expect(
      await organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).toBeNull();
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });

    const reoffer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(reoffer.status).toBe("pending");
  });
});

